<!doctype html><html lang="en"><head><meta charset="UTF-8"><title>Seeker Search</title><link rel="stylesheet" href="/project/public/assets/css/style.css"></head><body><div class="container"><h2>Search Seeker Database (AJAX)</h2><?php if (!empty($_GET['success'])): ?><div class="alert alert-success">Outreach sent successfully.</div><?php endif; ?><?php if (!empty($_GET['error'])): ?><div class="alert alert-error">Please provide all outreach fields.</div><?php endif; ?><div class="grid-2"><div><label>Keyword</label><input id="keyword" placeholder="skills/headline"></div><div><label>Location</label><input id="location" placeholder="location"></div><div><label>Min Experience</label><input id="min_experience" type="number" step="0.1"></div><div><label>Max Expected Salary</label><input id="max_expected_salary" type="number" step="0.01"></div></div><div class="actions"><button onclick="searchSeekers()">Search</button><a class="btn btn-secondary" href="index.php?route=recruiter/dashboard">Back</a></div><div id="results"></div><script>
function escapeHtml(str){return String(str||'').replace(/[&<>\"']/g,function(m){return({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'})[m];});}
const recruiterJobs=<?php echo json_encode(array_map(function($j){ return ['id'=>(int)$j['id'],'title'=>$j['title']];},$jobs)); ?>;
function renderJobOptions(){return recruiterJobs.map(function(job){return '<option value="'+job.id+'">'+escapeHtml(job.title)+'</option>';}).join('');}
function searchSeekers(){const params=new URLSearchParams({route:'api/recruiter/seekers',keyword:document.getElementById('keyword').value,location:document.getElementById('location').value,min_experience:document.getElementById('min_experience').value,max_expected_salary:document.getElementById('max_expected_salary').value});const xhr=new XMLHttpRequest();xhr.open('GET','index.php?'+params.toString(),true);xhr.onreadystatechange=function(){if(xhr.readyState===4){if(xhr.status!==200){document.getElementById('results').innerHTML='<div class="alert alert-error">Search failed.</div>';return;}const payload=JSON.parse(xhr.responseText);const seekers=payload.data||[];if(!seekers.length){document.getElementById('results').innerHTML='<p class="muted">No seekers found.</p>';return;}let html='<h3>Results</h3>';seekers.forEach(function(seeker){html+='<div class="dashboard-card" style="margin-bottom:10px">';html+='<p><strong>'+escapeHtml(seeker.name)+'</strong> ('+escapeHtml(seeker.email)+')</p>';html+='<p>Headline: '+escapeHtml(seeker.headline||'')+'</p>';html+='<p>Skills: '+escapeHtml(seeker.skills||'')+'</p>';html+='<p>Experience: '+escapeHtml(seeker.years_experience)+' years</p>';html+='<p>Location: '+escapeHtml(seeker.preferred_location||'')+'</p>';html+='<p>Expected Salary: '+escapeHtml(seeker.expected_salary||'')+'</p>';html+='<form method="post" action="index.php?route=recruiter/outreach/send">';html+='<input type="hidden" name="seeker_id" value="'+seeker.seeker_id+'">';html+='<label>Select Job</label><select name="job_id" required><option value="">Select job</option>'+renderJobOptions()+'</select>';html+='<label>Outreach Message</label><textarea name="message" required placeholder="Write outreach message"></textarea>';html+='<div class="actions"><button type="submit">Send Outreach</button></div>';html+='</form></div>';});document.getElementById('results').innerHTML=html;}};xhr.send();}
</script></div></body></html>
